        event: KeyEvent,
    ) {
        self.clipboard.serial(serial);
        if let Some(object) = self.focused
            && let Err(error) = self.send_input(
                object,
                InputEvent::Key {
                    action: KeyAction::Down,
                    keycode: event.raw_code,
                    repeat: 1,
                },
            )
        {
            self.fail(&error);
        }
